def is_perfect_cube(n):
    if n == 0:
        return True, 0
    sign = 1 if n > 0 else -1
    abs_n = abs(n)
    # Estimate the cube root
    root = round(abs_n**(1/3))
    # Check the cube
    if root**3 == abs_n:
        return True, sign * root
    return False, None

m_values = range(1, 15) # Check up to m=14
results = {}

for m in m_values:
    n_cubed = 8 * (m**3) - 65
    is_cube, n = is_perfect_cube(n_cubed)
    results[m] = (n_cubed, is_cube, n)

for m, (n_cubed, is_cube, n) in results.items():
    if is_cube:
        print(f"m={m}: n^3={n_cubed}, n={n}")

